import pytest
import uuid
from unittest.mock import Mock, AsyncMock, patch
from datetime import datetime

from app.services.booking_service import BookingService
from app.models.seat import Seat, SeatStatus
from app.models.booking import Booking, BookingStatus, PaymentStatus
from app.core.exceptions import (
    SeatNotFoundError,
    SeatAlreadyBookedError,
    BookingConflictError
)


@pytest.mark.asyncio
class TestBookingService:

    async def test_book_seat_success(self, db, redis_client, mock_event_publisher, sample_event, sample_seats):
        """Test successful seat booking"""
        from app.services.lock_service import DistributedLock

        lock_service = DistributedLock(redis_client)
        booking_service = BookingService(db, lock_service, mock_event_publisher)

        user_id = uuid.uuid4()
        seat = sample_seats[0]

        result = await booking_service.book_seat(
            user_id=user_id,
            event_id=sample_event.event_id,
            seat_id=seat.seat_id,
            idempotency_key="test-key-123"
        )

        assert result["success"] is True
        assert "booking_id" in result
        assert result["seat_id"] == str(seat.seat_id)

        # Verify seat is booked
        db.refresh(seat)
        assert seat.status == SeatStatus.BOOKED
        assert seat.booked_by == user_id

    async def test_book_seat_already_booked(self, db, redis_client, mock_event_publisher, sample_event, sample_seats):
        """Test booking an already booked seat"""
        from app.services.lock_service import DistributedLock

        lock_service = DistributedLock(redis_client)
        booking_service = BookingService(db, lock_service, mock_event_publisher)

        # Book the seat first
        seat = sample_seats[0]
        seat.status = SeatStatus.BOOKED
        seat.booked_by = uuid.uuid4()
        db.commit()

        # Try to book again
        user_id = uuid.uuid4()

        with pytest.raises(SeatAlreadyBookedError):
            await booking_service.book_seat(
                user_id=user_id,
                event_id=sample_event.event_id,
                seat_id=seat.seat_id,
                idempotency_key="test-key-456"
            )

