    async def test_idempotency(self, db, redis_client, mock_event_publisher, sample_event, sample_seats):
        """Test idempotency key prevents duplicate bookings"""
        from app.services.lock_service import DistributedLock

        lock_service = DistributedLock(redis_client)
        booking_service = BookingService(db, lock_service, mock_event_publisher)

        user_id = uuid.uuid4()
        seat = sample_seats[0]
        idempotency_key = "unique-key-999"

        # First booking
        result1 = await booking_service.book_seat(
            user_id=user_id,
            event_id=sample_event.event_id,
            seat_id=seat.seat_id,
            idempotency_key=idempotency_key
        )

        # Second booking with same key
        result2 = await booking_service.book_seat(
            user_id=user_id,
            event_id=sample_event.event_id,
            seat_id=seat.seat_id,
            idempotency_key=idempotency_key
        )

        assert result1["booking_id"] == result2["booking_id"]
        assert result2["is_duplicate"] is True

        # Verify only one booking exists
        bookings = db.query(Booking).filter(
            Booking.idempotency_key == idempotency_key
        ).all()
        assert len(bookings) == 1
